mapper.select:
SELECT H.TAGS FROM hashtag H
JOIN user_hashtag UH ON H.hashtag_idx = UH.hashtag_idx
WHERE UH.user_idx = #{user_idx, jdbcType=INTEGER}

SELECT H.TAGS FROM hashtag H
JOIN user_hashtag_like UHL ON H.hashtag_idx = UHL.hashtag_idx
WHERE UHL.user_idx = #{user_idx, jdbcType=INTEGER}

mapper.update:
UPDATE coach
SET TOKEN_BALANCE = TOKEN_BALANCE - #{amount, jdbcType=INTEGER}
WHERE USER_IDX = #{user_idx, jdbcType=INTEGER}

mapper.select:
select count(*) from likes_user
where liker_idx = #{login_idx}
and liked_user_idx = #{target_idx}
